Future<void> main() async {
  final app = CobaltScope.root(name: 'app')
    ..registerLazySingleton<Clock>(const ClockFactory())
    ..registerLazySingleton<Greeter>(const GreeterFactory());

  await app.init();
  print(app.get<Greeter>().greet('Cobalt'));
  await app.dispose();
}
